// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.helpers;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

class BindingAnalysisInvalidationCompositionTest {
	@Test
	void rewritingLeftOperandInvalidatesMemoizedRightInputTransition() {
		StatementPattern left = new StatementPattern(Var.of("old"), Var.of("p"), Var.of("o"));
		StatementPattern right = new StatementPattern(Var.of("s"), Var.of("q"), Var.of("z"));
		Join join = new Join(left, right);
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(join,
				EmptyBindingSet.getInstance());
		var before = analysis.childInput(join, right, analysis.rootContext());
		assertTrue(before.guaranteedNames().contains("old"));
		join.setLeftArg(new StatementPattern(Var.of("new"), Var.of("p2"), Var.of("o2")));
		analysis.invalidate();
		var after = analysis.childInput(join, right, analysis.rootContext());
		assertFalse(after.guaranteedNames().contains("old"));
		assertTrue(after.guaranteedNames().contains("new"));
	}
}
